with feeders as (
    select
        md5(upper('HUB_COVERAGE|' || (HUB_COVERAGE_BK__COVER_CODE))) as HUB_COVERAGE_HK
        , PREMIUM as SLAB_PREMIUM_RATE
        , AGE_LIMIT as AGE_LIMIT_BAND
        , TOTAL_SI as SUM_INSURED_SLAB_AMOUNT
        , PLAN_CODE as PLAN_REFERENCE
        , SR_NO as LINE_SEQUENCE_NUMBER
        , SECTION_ID as SECTION_REFERENCE
        , EFF_DATE as RATE_EFFECTIVE_DATE
        , PREM_FLAG as PREMIUM_APPLICABILITY_BASIS
        , 'BJAZ_STARPKG_COV_PREM_MST' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_starpkg_cov_prem_mst') }}
    where (nullif(trim(COVER_CODE),'')) is not null
),

resolved as (
    select
        HUB_COVERAGE_HK,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SLAB_PREMIUM_RATE end) as SLAB_PREMIUM_RATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then AGE_LIMIT_BAND end) as AGE_LIMIT_BAND,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SUM_INSURED_SLAB_AMOUNT end) as SUM_INSURED_SLAB_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PLAN_REFERENCE end) as PLAN_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then LINE_SEQUENCE_NUMBER end) as LINE_SEQUENCE_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SECTION_REFERENCE end) as SECTION_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RATE_EFFECTIVE_DATE end) as RATE_EFFECTIVE_DATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PREMIUM_APPLICABILITY_BASIS end) as PREMIUM_APPLICABILITY_BASIS,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_COVERAGE_HK
),

hashed as (
    select
        *,
        case when SLAB_PREMIUM_RATE is not null or AGE_LIMIT_BAND is not null or SUM_INSURED_SLAB_AMOUNT is not null or PLAN_REFERENCE is not null or LINE_SEQUENCE_NUMBER is not null or SECTION_REFERENCE is not null or RATE_EFFECTIVE_DATE is not null or PREMIUM_APPLICABILITY_BASIS is not null
                     then md5(upper(coalesce(cast(SLAB_PREMIUM_RATE as varchar), '') || '|' || coalesce(cast(AGE_LIMIT_BAND as varchar), '') || '|' || coalesce(cast(SUM_INSURED_SLAB_AMOUNT as varchar), '') || '|' || coalesce(cast(PLAN_REFERENCE as varchar), '') || '|' || coalesce(cast(LINE_SEQUENCE_NUMBER as varchar), '') || '|' || coalesce(cast(SECTION_REFERENCE as varchar), '') || '|' || coalesce(cast(RATE_EFFECTIVE_DATE as varchar), '') || '|' || coalesce(cast(PREMIUM_APPLICABILITY_BASIS as varchar), '')))
                end as SAT_COVERAGE_PREMIUM_RATE_SLAB_HASHDIFF
    from resolved
)

select * from hashed
where HUB_COVERAGE_HK is not null
  and SAT_COVERAGE_PREMIUM_RATE_SLAB_HASHDIFF is not null
